SELECT ?movieWithPoitier ?movieWithPoitierReleaseDate ?sacredPlanetReleaseDate WHERE {
  ?movieWithPoitier wdt:P161 wd:Q5791007.  # Damion Poitier as actor
  ?movieWithPoitier wdt:P577 ?movieWithPoitierReleaseDate.  

  wd:Q10636084 wdt:P577 ?sacredPlanetReleaseDate.  # Sacred Planet release date

  FILTER(?sacredPlanetReleaseDate > ?movieWithPoitierReleaseDate)
} ORDER BY ?movieWithPoitierReleaseDate LIMIT 1

SELECT ?movieWithPoitier ?movieWithPoitierReleaseDate ?sacredPlanetReleaseDate WHERE {
  ?movieWithPoitier wdt:P161 wd:Q5791007.  # Damion Poitier as actor
  ?movieWithPoitier wdt:P577 ?movieWithPoitierReleaseDate.  

  wd:Q10636084 wdt:P577 ?sacredPlanetReleaseDate.  # Sacred Planet release date

  FILTER(?sacredPlanetReleaseDate > ?movieWithPoitierReleaseDate)
} ORDER BY ?movieWithPoitierReleaseDate LIMIT 1

SELECT ?person ?birthPlace ?sport WHERE {
  {
    VALUES ?person { wd:Q204041 } # Angelique Kerber's Wikidata ID assumed
    ?person wdt:P106 wd:Q8470. # occupation: tennis player
    OPTIONAL { ?person wdt:P19 ?birthPlace. }
  }
  UNION
  {
    ?tournament wdt:P3452 "2005 China Open - Men's Doubles".
    ?match wdt:P641 wd:Q8470; # sport: tennis
           wdt:P1346 ?person. # winner
    ?person wdt:P106 wd:Q8470. # occupation: tennis player
  }
}

SELECT 
  (SELECT birthplace FROM tennis_players WHERE name = 'Angelique Kerber') AS Kerber_birthplace,
  (SELECT event FROM tennis_titles WHERE player IN (
     SELECT player FROM tennis_titles WHERE tournament = 'China Open' AND year = 2004 AND category = 'Men\'s Doubles'
  ) AND tournament = 'China Open' AND year = 2005 AND category = 'Men\'s Doubles' AND result = 'defending champion') AS defending_champion_event;

SELECT ?experimenterCast ?experimenterCastRole ?experimenterProducer ?manCampProducer WHERE {
  # Find the cast of 'Experimenter'
  ?experimenter wdt:P31 wd:Q11424; # instance of film
               rdfs:label "Experimenter"@en;
               wdt:P161 ?experimenterCast;
               wdt:P57 ?experimenterProducer. # producer

  ?experimenterCast wdt:P463 ?experimenterCastRole. 

  # Find producers of 'Man Camp'
  ?manCamp wdt:P31 wd:Q11424; # instance of film
           rdfs:label "Man Camp"@en;
           wdt:P57 ?manCampProducer.

  FILTER(LCASE(STR(?experimenterProducer)) = LCASE(STR(?manCampProducer)))
}

UNION

SELECT ?beetlejuiceActress WHERE {
  wd:Q28298 rdfs:label "Beetlejuice"@en;
             wdt:P161 ?castMember.
  ?castMember wdt:P106 wd:Q33999; # actress
              wdt:P345 ?imdbID.
  ?castMember ?roleProp ?roleValue.
  FILTER(CONTAINS(LCASE(STR(?roleValue)), "johnny depp"))
} LIMIT 10

SELECT ?series ?seriesLabel ?actress ?actressLabel WHERE {
  ?series wdt:P57 wd:Q217347;       # creator Hilarie Ross Burton
          wdt:P449 wd:Q12245.       # broadcast network The WB
  ?series wdt:P161 ?actress.        # cast member
  ?film wdt:P31 wd:Q11424;          # instance of film
        rdfs:label "Grace, Replaced"@en; 
        wdt:P161 ?actress.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
} LIMIT 10

SELECT ?band ?host ?show WHERE {
  ?band wdt:P31 wd:Q215380;                 # instance of band
    wdt:P527 ?member.                      # has member
  ?member rdfs:label ?host FILTER (LANG(?host) = "en").
  ?host wdt:P449 ?show.                    # hosted show
  ?show rdfs:label "You Can't See Me"@en.
  ?member wdt:P435 ?defariID.              # Defari membership check (optional)
  FILTER EXISTS {
    ?defari wdt:P31 wd:Q5;                 # Defari is human
    ?defari wdt:P1344 ?band.               # Defari involved in band
    ?defari rdfs:label "Defari"@en.
  }
} LIMIT 10

SELECT ?actor WHERE {
  ?wonderWomanFilm wdt:P31 wd:Q11424;  # film
                      rdfs:label "Wonder Woman"@en;
                      wdt:P577 ?wonderWomanReleaseDate.
  ?actor wdt:P161 ?wonderWomanFilm.   # cast member

  ?anomalisaFilm wdt:P31 wd:Q11424;
                 rdfs:label "Anomalisa"@en;
                 wdt:P577 ?anomalisaReleaseDate.
  ?actor wdt:P161 ?anomalisaFilm.

  ?fargoSeries wdt:P31 wd:Q5398426;   # TV series
               rdfs:label "Fargo"@en;
               wdt:P577 ?fargoPremiereDate.

  FILTER(YEAR(?anomalisaReleaseDate) > YEAR(?fargoPremiereDate))
  FILTER(?wonderWomanReleaseDate = "2017-06-02"^^xsd:date)
}

