SELECT ?host ?totalShows WHERE {
  ?show a tv:TelevisionShow ;
        tv:hasHost ?host .
  ?appearance tv:person ?person ;
              tv:televisionShow ?show .
  ?person foaf:name "Paul Melba" .
  ?host tv:hostedShowsCount ?totalShows .
  FILTER(?totalShows = 23)
}

SELECT ?host ?numShows WHERE {
  ?show a tv:TelevisionShow ;
        tv:hasParticipant tv:PaulMelba ;
        tv:country "United Kingdom" ;
        tv:host ?host .
  ?host tv:totalHostedShows ?numShows .
  FILTER(?numShows = 23)
}
